package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamClausesErrBank2 {
  private const val T = "Comparison, Synthesis & Error Correction"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("Pidurutalagala is the ___ mountain peak in Sri Lanka.", "highest", "higher", "most high", "high", "Superlative degree takes 'the + -est' for short adjectives like 'high'."),
    q("The Mahaweli is ___ than any other river flowing across Sri Lanka.", "longer", "longest", "more long", "long", "'Than any other' signals the comparative degree ('longer')."),
    q("No other bird in our garden sings ___ sweetly as the magpie robin.", "so", "more", "most", "very", "Negative equal comparison uses 'so ... as'."),
    q("Very few towns in the island are as ___ as Nuwara Eliya.", "cool", "cooler", "coolest", "more cool", "'As + positive degree + as' takes the base adjective 'cool'."),
    q("Good health is far ___ valuable than material wealth.", "more", "most", "much", "many", "Multi-syllable adjectives form their comparative with 'more'."),
    q("The ___ you climb up the mountain trail, the colder the air becomes.", "higher", "high", "highest", "more high", "Proportional comparison uses 'The + comparative..., the + comparative'."),
    q("Among all the contestants, Kavindi painted the ___ portrait.", "most realistic", "more realistic", "realistic", "realistically", "Comparing three or more requires the superlative 'the most realistic'."),
    q("This new edition of the atlas is much ___ than the old one.", "better", "good", "best", "more good", "Irregular comparative of 'good' is 'better'."),
    q("Yesterday's storm was the ___ we have experienced in ten years.", "worst", "worse", "most bad", "baddest", "Irregular superlative of 'bad' is 'worst'."),
    q("This brass temple bell rings ___ than the small tin handbell.", "louder", "loudest", "more loud", "loud", "Comparing two bells uses the comparative 'louder'."),
    q("Colombo is one of the ___ populated cities in Sri Lanka.", "most densely", "more densely", "densely", "very densely", "'One of the + superlative' requires 'most densely'."),
    q("She writes essays ___ carefully than anyone else in her class.", "more", "most", "much", "very", "Adverbs ending in '-ly' form comparatives with 'more'."),
    q("Of the two sisters, Tharushi is the ___ at solving geometry puzzles.", "quicker", "quickest", "quick", "more quick", "When comparing exactly two people, use the comparative ('the quicker')."),
    q("My grandfather's pocket watch runs as ___ as a new digital clock.", "accurately", "more accurately", "most accurately", "accurate", "'Runs' is an action verb modified by the positive adverb 'accurately' inside 'as ... as'."),
    q("The farther south we drove along the coast, the ___ the beaches looked.", "quieter", "quietest", "quiet", "more quiet", "Double comparative pattern uses 'the quieter'."),
    q("Gold is heavier ___ silver and aluminium.", "than", "then", "from", "to", "Standard comparatives take 'than', never 'then'."),
    q("This river is three times ___ than the canal near our school.", "wider", "wide", "widest", "more wide", "Multiplier + comparative + 'than' is grammatically standard ('three times wider than')."),
    q("My suitcase weighs almost the same ___ yours.", "as", "than", "like", "with", "'The same' always pairs with 'as'."),
    q("Our new library hall is twice as ___ as the old reading room.", "spacious", "more spacious", "most spacious", "spaciously", "Between 'as ... as', use the positive adjective 'spacious'."),
    q("Nadeesha arrived ___ than expected because the highway was clear.", "earlier", "earliest", "early", "more early", "'Earlier' is the comparative form of 'early'."),
    q("Who ran the ___ in yesterday's 400-metre relay final?", "fastest", "faster", "more fast", "fastly", "Superlative adverb among a group of runners is 'fastest'."),
    q("Choose the grammatically correct sentence using 'prefer'.", "She prefers tea to coffee.", "She prefers tea than coffee.", "She prefers tea over coffee.", "She prefers tea from coffee.", "'Prefer' compares two nouns with 'to' ('prefer X to Y')."),
    q("Identify the error-free sentence with 'senior'.", "He is senior to me by two years.", "He is senior than me by two years.", "He is more senior to me here.", "He is senior from me by years.", "Latin comparatives ('senior, junior, superior, inferior') take 'to'."),
    q("Select the grammatically accurate sentence using 'despite'.", "Despite the rain, the match continued.", "Despite of the rain, the match continued.", "In spite the rain, the match continued.", "Although the rain, the match continued.", "'Despite' never takes 'of'; 'in spite of' requires 'of'."),
    q("Choose the sentence with correct inversion after 'scarcely'.", "Scarcely had he arrived when it poured.", "Scarcely had he arrived than it poured.", "Scarcely he had arrived when it poured.", "Scarcely did he arrived when it poured.", "Negative inversion uses 'Scarcely + had + subject + V3 + when'."),
    q("Which sentence uses 'look forward to' correctly?", "I look forward to meeting you soon.", "I look forward to meet you soon.", "I look forward for meeting you soon.", "I look forward meeting you right now.", "'Look forward to' takes a gerund ('meeting')."),
    q("Identify the grammatically correct sentence starting with 'each of'.", "Each of the boys has a neat uniform.", "Each of the boys have a neat uniform.", "Each of the boy has a neat uniform.", "Each of the boys are having a uniform.", "'Each of + plural noun' takes a singular verb ('has')."),
    q("Select the sentence with zero errors regarding 'scenery'.", "The scenery in Ella is breathtaking.", "The sceneries in Ella are breathtaking.", "The scenery in Ella are breathtaking.", "The sceneries in Ella is breathtaking.", "'Scenery' is uncountable and takes no '-s' and a singular verb ('is')."),
    q("Choose the grammatically correct sentence about 'advice'.", "He gave me some helpful advice.", "He gave me some helpful advices.", "He gave me a helpful advice.", "He gave me many helpful advices.", "'Advice' is uncountable; use 'some advice' or 'a piece of advice'."),
    q("Identify the error-free sentence using uncountable 'luggage'.", "My luggage was checked at the gate.", "My luggages were checked at the gate.", "My luggage were checked at the gate.", "A luggages were checked at the gate.", "'Luggage' is an uncountable noun taking a singular verb ('was')."),
    q("Select the grammatically accurate sentence free of redundancy.", "Please return the borrowed library book.", "Please return back the borrowed book.", "Please repeat again the final paragraph.", "Kindly revert back to the library desk.", "Do not add 'back' after 'return' or 'again' after 'repeat'."),
    q("Identify the error-free sentence regarding 'cope'.", "He can cope with intense exam pressure.", "He can cope up with exam pressure.", "He can cope up the intense pressure.", "He is coping up with exam pressure.", "The standard idiom is 'cope with', never 'cope up with'."),
    q("Choose the error-free sentence regarding 'discuss'.", "We discussed the sports meet budget.", "We discussed about the sports meet budget.", "We discussed on the sports meet budget.", "We discussed over the sports meet budget.", "'Discuss' is transitive and takes a direct object without 'about'."),
    q("Select the grammatically accurate sentence using 'entered'.", "He entered the quiet hall silently.", "He entered into the hall silently.", "He entered inside the hall silently.", "He entered to the quiet hall silently.", "'Enter' (go into a room) does not take 'into'."),
    q("Identify the sentence pairing 'ago' with the right tense.", "The train left ten minutes ago.", "The train has left ten minutes ago.", "The train had leaving ten minutes ago.", "The train leaves ten minutes ago.", "Specific finished past time ('ten minutes ago') requires Simple Past, not Present Perfect."),
    q("Choose the grammatically correct Second Conditional sentence.", "If I were you, I would apologize.", "If I was you, I would apologize.", "If I am you, I would apologize.", "If I were you, I will apologize.", "Second Conditional hypothetical advice uses 'If I were you, I would...'."),
    q("Select the correct sentence using negative 'hardly'.", "I could hardly hear his soft whisper.", "I couldn't hardly hear his soft whisper.", "I could hard hear his soft whisper.", "I couldn't scarcely hear his whisper.", "'Hardly' is already negative, so avoid double negatives like 'couldn't hardly'."),
    q("Identify the grammatically correct sentence with 'neither ... nor'.", "Neither Saman nor his friends are absent.", "Neither Saman nor his friends is absent.", "Neither Saman or his friends are absent.", "Neither Saman nor his friend are absent.", "With 'neither ... nor', the verb agrees with the closer subject ('friends' -> 'are')."),
    q("Choose the error-free sentence with 'congratulated'.", "She congratulated him on his victory.", "She congratulated him for his victory.", "She congratulated to him on victory.", "She congratulated him about his victory.", "Correct collocation is 'congratulate someone on something'."),
    q("Select the sentence with correct tense sequence for a universal truth.", "He said that honesty is the best policy.", "He said that honesty was being policy.", "He told that honesty is the best policy.", "He said me that honesty is best policy.", "Universal truths keep Present Simple in reported speech; 'say' has no indirect object without 'to'."),
    q("Identify the grammatically correct embedded 'where' clause.", "Tell me where the science lab is.", "Tell me where is the science lab.", "Tell me where does science lab be.", "Tell me where was being the lab.", "Embedded indirect questions follow statement word order (subject + verb)."),
    q("Choose the sentence with proper indirect question order.", "Do you know when the bus arrives?", "Do you know when does the bus arrive?", "Do you know when arrives the bus?", "Do you know when did the bus arrived?", "Inside 'Do you know...', the embedded clause drops 'does' and uses statement order."),
    q("Select the error-free sentence starting with 'one of my'.", "One of my cousins lives in Galle.", "One of my cousin lives in Galle.", "One of my cousins live in Galle.", "One of my cousin live in Galle.", "'One of + plural noun' takes a singular verb ('lives')."),
    q("Identify the grammatically correct sentence about a sum of money.", "Ten thousand rupees is a fair price.", "Ten thousand rupees are a fair price.", "Ten thousand rupee is a fair price.", "Ten thousand rupees were being fair.", "A single sum of money takes a singular verb ('is')."),
    q("Choose the error-free sentence with the plural noun 'police'.", "The police have arrested the thief.", "The police has arrested the thief.", "The polices have arrested the thief.", "The police is arrest the thief.", "'Police' is always plural in form and verb agreement ('have arrested')."),
    q("Select the grammatically correct sentence about 'trousers'.", "This pair of trousers needs ironing.", "This pair of trousers need ironing.", "These pair of trousers needs ironing.", "This trouser need quick ironing.", "'Pair' is the singular head noun, so it takes 'needs'."),
    q("Identify the correct negative imperative sentence.", "Never judge a book by its cover.", "Not ever judging a book by cover.", "Never to judge a book by its cover.", "Don't never judge a book by cover.", "Imperatives begin directly with 'Never + base verb' (avoid double negatives)."),
    q("Choose the grammatically sound sentence opening with 'Being tired'.", "Being tired, he went to bed early.", "Having tire, he went to bed early.", "Been tired, he went to bed early.", "Being tiring, he went to bed early.", "'Being tired' (having the feeling) correctly matches the subject 'he'."),
    q("Identify the error-free participle sentence with no dangling modifier.", "Walking down the lane, I saw Nimal.", "Walking down the lane, a snake bit him.", "Walking down the lane, the sun shone.", "Walking down the lane, trees waved.", "The implied subject of 'Walking' must match the main clause subject ('I')."),
    q("Combine cleanly: 'He was ill. He attended school.'", "Although he was ill, he attended school.", "Although he was ill, but he attended.", "Despite he was ill, he attended school.", "Because he was ill, he attended school.", "'Although' introduces contrast and never pairs with 'but' in the main clause."),
    q("Combine cleanly: 'Work steadily. You will miss the deadline.'", "Work steadily, or you will miss the deadline.", "Work steadily, so you will miss the deadline.", "Work steadily, unless you miss deadline.", "Work steadily, because you miss deadline.", "'Or' joins a command with the consequence of failing to obey it."),
    q("Combine cleanly: 'She opened the box. She found a silver coin.'", "Opening the box, she found a silver coin.", "Opened the box, she found a silver coin.", "To open the box, she found a silver coin.", "Open the box, she found a silver coin.", "Present participle 'Opening' shows two quick sequential actions by the same subject."),
    q("Combine using 'too ... to': 'The tea is very hot. I cannot drink it.'", "The tea is too hot for me to drink.", "The tea is too hot for me to drink it.", "The tea is very hot for me to drink it.", "The tea is so hot that to drink it.", "In 'too ... to', omit the redundant trailing pronoun 'it'."),
    q("Combine using 'so ... that': 'The box was very heavy. No one lifted it.'", "The box was so heavy that no one lifted it.", "The box was such heavy that no one lifted it.", "The box was too heavy that no one lifted it.", "The box was so heavy for no one lifted it.", "'So + adjective + that + clause' expresses result."),
    q("Combine using 'enough': 'He is clever. He can solve the puzzle.'", "He is clever enough to solve the puzzle.", "He is enough clever to solve the puzzle.", "He is too clever to solve the puzzle.", "He is clever enough solving the puzzle.", "'Enough' comes AFTER the adjective ('clever enough') before a to-infinitive."),
    q("Select the best synthesis: 'Both boys were late. Neither apologized.'", "Though both boys were late, neither apologized.", "Though both boys were late, yet none didn't.", "Despite both boys late, neither apologized.", "Unless both boys were late, neither apologized.", "'Though + clause' cleanly links the two contrasting facts."),
    q("Identify the grammatically correct sentence with 'no sooner'.", "No sooner had I stepped out than it rained.", "No sooner had I stepped out when it rained.", "No sooner I stepped out than it rained.", "No sooner did I stepped out than it rained.", "'No sooner + had + subject + V3' pairs strictly with 'than'."),
    q("Choose the error-free sentence using 'since' for ongoing duration.", "She has been ill since last Friday.", "She is ill since last Friday.", "She has been ill from last Friday.", "She was ill since last Friday.", "Duration continuing up to now uses Present Perfect + 'since'."),
    q("Select the correct sentence expressing a five-year stay.", "We lived in Jaffna for five years.", "We lived in Jaffna since five years.", "We lived in Jaffna during five years.", "We live in Jaffna since five years.", "A period of time takes 'for', never 'since'."),
    q("Identify the sentence with accurate pronoun case after 'between'.", "Between you and me, the plan looks risky.", "Between you and I, the plan looks risky.", "Between your and me, the plan looks risky.", "Between you and myself, the plan is risky.", "After preposition 'between', use object pronouns ('you and me')."),
    q("Choose the error-free sentence with pronoun case after 'for'.", "This parcel is for my sister and me.", "This parcel is for my sister and I.", "This parcel is for I and my sister.", "This parcel is for myself and sister.", "Preposition 'for' requires the object pronoun 'me'."),
    q("Select the correct comparison sentence about handwriting.", "My handwriting is neater than my brother's.", "My handwriting is neater than my brother.", "My handwriting is neatest than my brother's.", "My handwriting is more neat than brother.", "Compare like with like ('my handwriting' vs. 'my brother's [handwriting]')."),
    q("Identify the grammatically correct sentence comparing town climates.", "The climate of Kandy is cooler than that of Galle.", "The climate of Kandy is cooler than Galle.", "The climate of Kandy is coolest than Galle.", "The climate of Kandy is cooler than those of Galle.", "Singular 'the climate' is substituted by 'that of' in comparison."),
    q("Choose the error-free sentence comparing city streets.", "The streets of Colombo are wider than those of Matale.", "The streets of Colombo are wider than Matale.", "The streets of Colombo are wider than that of Matale.", "The streets of Colombo is wider than Matale.", "Plural 'the streets' requires 'those of' to compare like items."),
    q("Select the sentence without misplaced modifiers.", "Hanging on the wall, the painting looked lovely.", "Hanging on the wall, I admired the painting.", "Hanging on the wall, my cousin saw a bird.", "Hanging on the wall, the room brightened me.", "The participle 'Hanging on the wall' clearly modifies 'the painting'."),
    q("Identify the grammatically accurate sentence comparing speech fluency.", "He speaks English as fluently as his teacher.", "He speaks English so fluently as his teacher.", "He speaks English as fluent as his teacher.", "He speaks English more fluent than his teacher.", "Action verb 'speaks' takes the adverb 'fluently' in 'as ... as'."),
    q("Choose the correct sentence using 'hardly ever'.", "He hardly ever misses morning assembly.", "He hardly never misses morning assembly.", "He does hardly ever misses assembly.", "He is hardly ever miss morning assembly.", "'Hardly ever' cleanly means almost never."),
    q("Identify the error-free sentence with 'It is high time'.", "It is high time we started revising.", "It is high time we start revising.", "It is high time we will start revising.", "It is high time for start revising.", "'It is high time + subject' takes a past subjunctive verb ('started')."),
    q("Select the grammatically correct 'wish' sentence for the present.", "I wish I knew how to play the violin.", "I wish I know how to play the violin.", "I wish I will know how to play violin.", "I wish I am knowing how to play violin.", "Wishes about present reality use Simple Past ('knew')."),
    q("Choose the error-free sentence beginning with 'Supposing'.", "Supposing we miss the bus, what shall we do?", "Supposing if we miss the bus, what we do?", "Supposing we will miss the bus, what do?", "Supposing that missing the bus, what then?", "'Supposing' means 'if', so do not write 'supposing if'."),
    q("Identify the correct past Wh-question with 'why'.", "Why did she refuse the invitation?", "Why she refused the invitation?", "Why did she refused the invitation?", "Why was she refuse the invitation?", "Wh-question in Simple Past uses 'did + subject + base verb'."),
    q("Select the error-free polite question with 'what time'.", "Could you tell me what time the train leaves?", "Could you tell me what time leaves the train?", "Could you tell me what time does train leave?", "Could you tell me what time did train left?", "Polite indirect request keeps 'the train leaves' in statement order."),
    q("Choose the grammatically correct sentence with 'insisted'.", "She insisted on paying for her own ticket.", "She insisted to pay for her own ticket.", "She insisted on pay for her own ticket.", "She insisted for paying her own ticket.", "'Insist' takes 'on + gerund' ('insisted on paying')."),
    q("Identify the error-free sentence using 'prevented'.", "We prevented the stray dog from entering.", "We prevented the stray dog to enter.", "We prevented the stray dog for entering.", "We prevented the stray dog enter inside.", "'Prevent + object + from + -ing' is the standard pattern."),
    q("Select the correct sentence using 'accused'.", "He accused the cyclist of careless riding.", "He accused the cyclist for careless riding.", "He accused the cyclist with careless riding.", "He accused the cyclist on careless riding.", "'Accuse someone of' requires the preposition 'of'."),
    q("Choose the error-free sentence using 'proud'.", "The villagers are proud of their heritage.", "The villagers are proud for their heritage.", "The villagers are proud about their heritage.", "The villagers are proud with their heritage.", "'Proud' always pairs with 'of'."),
    q("Identify the grammatically correct sentence using 'interested'.", "I am interested in collecting postage stamps.", "I am interesting in collecting postage stamps.", "I am interested for collecting postage stamps.", "I am interested to collect postage stampings.", "Feelings take '-ed' ('interested') + preposition 'in' + gerund."),
    q("Select the correct sentence using 'so fascinating'.", "The documentary was so fascinating that we clapped.", "The documentary was so fascinated that we clapped.", "The documentary was too fascinating that we clapped.", "The documentary was such fascinating we clapped.", "Things causing interest take '-ing' ('fascinating') inside 'so ... that'."),
    q("Choose the error-free sentence starting with 'Every child'.", "Every child and every adult needs clean water.", "Every child and every adult need clean water.", "Every children and adults needs clean water.", "Every child and adult are needing water.", "Compound subjects introduced by 'Every' always take a singular verb ('needs')."),
    q("Identify the grammatically correct sentence with 'Either Kasun or'.", "Either Kasun or his brother has the lab key.", "Either Kasun or his brother have the lab key.", "Either Kasun nor his brother has the key.", "Either Kasun or his brother are having key.", "Singular closer subject ('brother') with 'either ... or' takes 'has'."),
    q("Select the error-free sentence starting with 'Many a student'.", "Many a student dreams of becoming a doctor.", "Many a student dream of becoming a doctor.", "Many a students dreams of becoming doctor.", "Many a student are dreaming to be doctor.", "'Many a + singular noun' takes a singular verb ('dreams')."),
    q("Choose the grammatically correct sentence with 'A number of'.", "A number of tourists are visiting Ella today.", "A number of tourists is visiting Ella today.", "The number of tourists are visiting Ella.", "A number of tourist are visiting Ella today.", "'A number of + plural noun' means 'several' and takes a plural verb ('are')."),
    q("Identify the error-free sentence with 'The number of'.", "The number of wild elephants is decreasing.", "The number of wild elephants are decreasing.", "The number of wild elephant is decreasing.", "A number of wild elephants is decreasing.", "'The number of' refers to a single numerical figure and takes a singular verb ('is')."),
    q("Select the correct sentence with 'Not only ... but also'.", "Not only the boys but also their coach was delighted.", "Not only the boys but also their coach were delighted.", "Not only the boys and also their coach was happy.", "Not only boys but their coach were delighted.", "With 'not only ... but also', the verb agrees with the closer subject ('coach' -> 'was')."),
    q("Choose the error-free sentence about 'Two hours'.", "Two hours is enough to complete Paper I.", "Two hours are enough to complete Paper I.", "Two hour is enough to complete Paper I.", "Two hours were being enough for Paper I.", "A fixed span of time considered as a single unit takes a singular verb ('is')."),
    q("Identify the grammatically correct sentence beginning 'There are'.", "There are plenty of reference books on the shelf.", "There is plenty of reference books on the shelf.", "There are plenty of reference book on shelf.", "There have plenty of books on the shelf.", "Subject after 'There' is plural ('books'), requiring 'are'."),
    q("Select the error-free sentence opening with 'Here'.", "Here comes the school cricket team!", "Here come the school cricket team!", "Here comes the school cricket players!", "Here are coming the cricket team!", "Singular collective unit 'team' pairs with 'comes'."),
    q("Choose the correct sentence using 'would rather'.", "I would rather stay home than go out.", "I would rather to stay home than go out.", "I would rather stay home than to go out.", "I would rather staying home than going out.", "'Would rather + bare infinitive + than + bare infinitive' keeps both verbs bare."),
    q("Identify the error-free inverted Third Conditional sentence.", "Had I known earlier, I would have helped.", "If I had knew earlier, I would help.", "Had I know earlier, I would have helped.", "If I knew earlier, I would have helped.", "Inverted Third Conditional uses 'Had + subject + V3, subject + would have + V3'."),
    q("Select the grammatically correct sentence using 'ought'.", "You ought to respect your elders always.", "You ought respecting your elders always.", "You ought to respected your elders always.", "You ought that you respect your elders.", "'Ought' is followed by a to-infinitive ('ought to respect')."),
    q("Choose the error-free sentence starting with 'Seldom'.", "Seldom have we seen such brilliant teamwork.", "Seldom we have seen such brilliant teamwork.", "Seldom has we seen such brilliant teamwork.", "Seldom did we saw such brilliant teamwork.", "Sentence-initial negative adverbs like 'Seldom' trigger auxiliary inversion ('have we seen')."),
    q("Identify the correct sentence starting with negative 'Little'.", "Little did she realize how close the finish line was.", "Little she realized how close finish line was.", "Little did she realized how close line was.", "Little was she realize how close line was.", "'Little' at the start inverts with 'did + subject + base verb'."),
    q("Select the error-free reported question with 'whether'.", "She asked whether I had brought my atlas.", "She asked that whether I brought my atlas.", "She asked if did I bring my atlas.", "She asked me whether had I brought atlas.", "Never write 'that whether'; indirect yes/no questions keep statement order."),
    q("Choose the grammatically correct sentence using 'ordered'.", "The doctor ordered the patient to rest indoors.", "The doctor ordered to the patient to rest.", "The doctor ordered that the patient resting.", "The doctor ordered the patient rest indoors.", "'Order + object + to-infinitive' takes no 'to' after 'order'."),
    q("Identify the error-free sentence describing a sharp knife.", "This sharp knife is easy to slice bread with.", "This sharp knife is easily to slice bread.", "This sharp knife is easy for slice bread.", "This sharp knife is easy to slicing bread.", "'Easy + to-infinitive' describes the noun cleanly."),
    q("Select the grammatically correct sentence using 'due to'.", "We stayed at home due to the heavy downpour.", "We stayed at home due to it rained heavily.", "We stayed at home because the heavy rain.", "We stayed at home owing that it rained.", "'Due to' must be followed by a noun phrase ('the heavy downpour'), not a full clause."),
    q("Choose the error-free sentence contrasting 'fewer' vs 'less'.", "No fewer than twenty schools joined the festival.", "No less than twenty schools joined the festival.", "Not few than twenty schools joined the festival.", "No lesser than twenty schools joined festival.", "Use 'fewer' with countable plural nouns ('schools'), 'less' with uncountable nouns."),
    q("Identify the grammatically correct sentence comparing sugar amounts.", "There is less sugar in this cup than in that one.", "There is fewer sugar in this cup than that.", "There are less sugar in this cup than yours.", "There is lesser sugar in this cup than yours.", "Uncountable noun 'sugar' takes singular 'is' and 'less'.")
  )
}
